package config

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestResolveDefaults(t *testing.T) {
	cfg := Default()
	r, err := Resolve(cfg, Overrides{})
	if err != nil {
		t.Fatalf("resolve: %v", err)
	}
	if r.Provider.Type != "local" {
		t.Fatalf("expected local provider by default, got %q", r.Provider.Type)
	}
	if r.Loop != LoopInteractive {
		t.Fatalf("expected interactive loop, got %q", r.Loop)
	}
	if !strings.Contains(r.System, "erg") {
		t.Fatal("system prompt should include the base")
	}
}

func TestResolveShapeAndOverrides(t *testing.T) {
	cfg := Default()
	r, err := Resolve(cfg, Overrides{Shape: "spec-implementer"})
	if err != nil {
		t.Fatalf("resolve: %v", err)
	}
	if r.Loop != LoopOneshot || r.MaxTurns != 100 {
		t.Fatalf("shape not applied: %+v", r)
	}
	if !strings.Contains(r.System, "specification") {
		t.Fatal("shape system append missing")
	}

	// Override provider and model over the shape.
	r, err = Resolve(cfg, Overrides{Shape: "spec-implementer", Provider: "openai", Model: "gpt-x"})
	if err != nil {
		t.Fatalf("resolve override: %v", err)
	}
	if r.Provider.Type != "openai" || r.Model != "gpt-x" {
		t.Fatalf("overrides not applied: %+v", r)
	}
}

func TestResolveUnknownShapeAndProvider(t *testing.T) {
	cfg := Default()
	if _, err := Resolve(cfg, Overrides{Shape: "nope"}); err == nil {
		t.Fatal("expected unknown shape error")
	}
	if _, err := Resolve(cfg, Overrides{Provider: "nope"}); err == nil {
		t.Fatal("expected unknown provider error")
	}
}

func TestLoadMergesFile(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.json")
	os.WriteFile(path, []byte(`{"default_provider":"openai","shapes":{"x":{"loop":"oneshot","system":"custom"}}}`), 0o644)
	t.Setenv("ERG_CONFIG", path)

	cfg, err := Load()
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	if cfg.DefaultProvider != "openai" {
		t.Fatalf("merge failed: %q", cfg.DefaultProvider)
	}
	if _, ok := cfg.Shapes["x"]; !ok {
		t.Fatal("user shape not merged")
	}
	// Built-in shapes survive the merge.
	if _, ok := cfg.Shapes["design-partner"]; !ok {
		t.Fatal("default shapes should remain after merge")
	}
}

func TestLoadErrorsWhenExplicitConfigMissing(t *testing.T) {
	missing := filepath.Join(t.TempDir(), "does-not-exist.json")
	t.Setenv("ERG_CONFIG", missing)

	if _, err := Load(); err == nil {
		t.Fatal("expected error when ERG_CONFIG names a missing file")
	}
}

func TestResolveComposesSkills(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "deploy")
	os.MkdirAll(dir, 0o755)
	os.WriteFile(filepath.Join(dir, "SKILL.md"),
		[]byte("---\nname: deploy\ndescription: how to ship\n---\nRun make deploy."), 0o644)

	cfg := Default()
	cfg.Shapes["shipper"] = Shape{Name: "shipper", Loop: LoopOneshot, Skills: []string{dir}}
	r, err := Resolve(cfg, Overrides{Shape: "shipper"})
	if err != nil {
		t.Fatalf("resolve: %v", err)
	}
	for _, want := range []string{"# Skills", "Skill: deploy", "Run make deploy."} {
		if !strings.Contains(r.System, want) {
			t.Fatalf("missing %q in system prompt:\n%s", want, r.System)
		}
	}
}

func TestResolveMissingSkillErrors(t *testing.T) {
	cfg := Default()
	cfg.Shapes["x"] = Shape{Name: "x", Skills: []string{"/no/such/skill/dir"}}
	if _, err := Resolve(cfg, Overrides{Shape: "x"}); err == nil {
		t.Fatal("expected error for a missing skill")
	}
}

func TestSystemFromFilePrefix(t *testing.T) {
	dir := t.TempDir()
	promptFile := filepath.Join(dir, "coder.md")
	os.WriteFile(promptFile, []byte("You are a careful coding agent."), 0o644)

	cfg := Default()
	cfg.Shapes["coder"] = Shape{Name: "coder", Loop: LoopInteractive, System: "FILE: " + promptFile}
	r, err := Resolve(cfg, Overrides{Shape: "coder"})
	if err != nil {
		t.Fatalf("resolve: %v", err)
	}
	if !strings.Contains(r.System, "careful coding agent") {
		t.Fatalf("FILE: prompt not loaded:\n%s", r.System)
	}
}

func TestSystemFromFileMissingErrors(t *testing.T) {
	cfg := Default()
	cfg.Shapes["x"] = Shape{Name: "x", System: "FILE: /no/such/prompt.md"}
	if _, err := Resolve(cfg, Overrides{Shape: "x"}); err == nil {
		t.Fatal("expected error for a missing FILE: prompt")
	}
}

func TestAgentsHierarchyOrderAndBoundary(t *testing.T) {
	root := t.TempDir()
	os.Mkdir(filepath.Join(root, ".git"), 0o755) // repo root: the walk stops here
	os.WriteFile(filepath.Join(root, "AGENTS.md"), []byte("ROOT RULES"), 0o644)
	sub := filepath.Join(root, "svc", "api")
	os.MkdirAll(sub, 0o755)
	os.WriteFile(filepath.Join(sub, "AGENTS.md"), []byte("API RULES"), 0o644)

	got, err := agentsHierarchy(sub)
	if err != nil {
		t.Fatalf("hierarchy: %v", err)
	}
	ri, ai := strings.Index(got, "ROOT RULES"), strings.Index(got, "API RULES")
	if ri < 0 || ai < 0 {
		t.Fatalf("both AGENTS.md should load:\n%s", got)
	}
	if ri > ai {
		t.Fatalf("outermost (ROOT) should come before nearest (API):\n%s", got)
	}
}

func TestAgentsHierarchyStopsAtGitRoot(t *testing.T) {
	root := t.TempDir()
	os.WriteFile(filepath.Join(root, "AGENTS.md"), []byte("ABOVE REPO"), 0o644)
	repo := filepath.Join(root, "repo")
	os.MkdirAll(filepath.Join(repo, ".git"), 0o755)
	os.WriteFile(filepath.Join(repo, "AGENTS.md"), []byte("REPO RULES"), 0o644)

	got, err := agentsHierarchy(repo)
	if err != nil {
		t.Fatalf("hierarchy: %v", err)
	}
	if !strings.Contains(got, "REPO RULES") {
		t.Fatal("repo AGENTS.md should load")
	}
	if strings.Contains(got, "ABOVE REPO") {
		t.Fatal("walk must not ascend above the git root")
	}
}

func TestAutoInstructionsToggle(t *testing.T) {
	cfg := Default()
	if !cfg.autoInstructionsEnabled() {
		t.Fatal("auto-instructions should default on")
	}
	off := false
	cfg.AutoInstructions = &off
	if cfg.autoInstructionsEnabled() {
		t.Fatal("auto-instructions should be off when set false")
	}
}

func TestDefaultCompactAt(t *testing.T) {
	if got := Default().CompactAt; got != 12000 {
		t.Fatalf("expected default compact_at 12000, got %d", got)
	}
}

func TestNoDefaultProviderErrors(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.json")
	os.WriteFile(path, []byte(`{"providers":{"litellm":{"type":"openai","base_url":"http://x/v1","model":"m"}},"shapes":{"s":{"loop":"oneshot","provider":"litellm","model":"m"}}}`), 0o644)
	t.Setenv("ERG_CONFIG", path)

	cfg, err := Load()
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	// Bare run (no provider/shape) must error and list available providers,
	// rather than silently falling back to the built-in local provider.
	_, err = Resolve(cfg, Overrides{})
	if err == nil || !strings.Contains(err.Error(), "no default_provider") || !strings.Contains(err.Error(), "litellm") {
		t.Fatalf("expected no-default-provider error listing litellm, got %v", err)
	}
	// A shape that names a provider still resolves.
	if _, err := Resolve(cfg, Overrides{Shape: "s"}); err != nil {
		t.Fatalf("shape with a provider should resolve: %v", err)
	}
	// An explicit --provider still resolves.
	if _, err := Resolve(cfg, Overrides{Provider: "litellm"}); err != nil {
		t.Fatalf("explicit provider should resolve: %v", err)
	}
}

func TestComposeSystemFromFiles(t *testing.T) {
	dir := t.TempDir()
	instr := filepath.Join(dir, "AGENTS.md")
	os.WriteFile(instr, []byte("PROJECT RULE"), 0o644)
	shape := Shape{System: "APPEND", Instr: []string{instr}}
	got, err := composeSystem("BASE", shape, false)
	if err != nil {
		t.Fatalf("compose: %v", err)
	}
	for _, want := range []string{"BASE", "APPEND", "PROJECT RULE"} {
		if !strings.Contains(got, want) {
			t.Fatalf("missing %q in %q", want, got)
		}
	}
}

// Package config holds erg's durable settings and the shape definitions that
// configure the engine for a job. It is plain data: it parses config files and
// resolves the effective run settings, but it never imports the provider,
// tool, or driver packages, so the dependency graph stays acyclic.
package config

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

// LoopMode selects which driver runs a shape.
type LoopMode string

const (
	LoopInteractive LoopMode = "interactive"
	LoopOneshot     LoopMode = "oneshot"
	LoopObserve     LoopMode = "observe"
)

// ProviderConfig describes one model backend. Type selects the adapter family;
// the rest is endpoint and auth detail. A static endpoint variant is a config
// block, never a new Go type.
type ProviderConfig struct {
	Type      string            `json:"type"`                  // openai | anthropic | local
	BaseURL   string            `json:"base_url,omitempty"`    // endpoint root
	APIKeyEnv string            `json:"api_key_env,omitempty"` // env var holding the key
	Model     string            `json:"model,omitempty"`       // default model for this provider
	Headers   map[string]string `json:"headers,omitempty"`     // extra request headers
	// Params are extra request-body fields merged into each request (sampling
	// controls such as temperature, top_p, top_k, repetition_penalty). They are
	// passed through verbatim, so backend-specific keys (forwarded by an
	// OpenAI-compatible proxy like LiteLLM) work without adapter changes.
	Params map[string]any `json:"params,omitempty"`
}

// ObserveConfig wires an observe shape: where events come from, what fires a
// reaction, and the prompt template that runs when one does.
type ObserveConfig struct {
	Source  SourceConfig  `json:"source"`
	Trigger TriggerConfig `json:"trigger"`
	Prompt  string        `json:"prompt"` // may contain {{.Event}}
}

// SourceConfig selects an observe source.
type SourceConfig struct {
	Kind    string   `json:"kind"`              // stdin | file | exec
	Path    string   `json:"path,omitempty"`    // file source
	Command []string `json:"command,omitempty"` // exec source
}

// TriggerConfig selects when a reaction fires.
type TriggerConfig struct {
	Kind       string `json:"kind"`                  // every | match
	Pattern    string `json:"pattern,omitempty"`     // regexp for match
	DebounceMS int    `json:"debounce_ms,omitempty"` // coalesce rapid events
}

// Shape is a named bundle that configures the engine for one job. Shapes are
// files kept in a repo; they double as subagent roles for the task tool.
type Shape struct {
	Name       string         `json:"name"`
	Loop       LoopMode       `json:"loop"`
	Provider   string         `json:"provider,omitempty"`
	Model      string         `json:"model,omitempty"`
	Effort     string         `json:"effort,omitempty"`
	System     string         `json:"system,omitempty"`       // appended to the base prompt
	SystemFile string         `json:"system_file,omitempty"`  // @file alternative to System
	Tools      []string       `json:"tools,omitempty"`        // enabled tool names (empty = all core)
	Skills     []string       `json:"skills,omitempty"`       // SKILL.md dirs to load
	Instr      []string       `json:"instructions,omitempty"` // project instruction files
	MaxTurns   int            `json:"max_turns,omitempty"`
	Observe    *ObserveConfig `json:"observe,omitempty"`
}

// Config is the whole durable configuration.
type Config struct {
	DefaultProvider string `json:"default_provider"`
	DefaultShape    string `json:"default_shape,omitempty"`
	SystemBase      string `json:"system_base"`
	// CompactAt is the model-visible window token estimate that triggers
	// automatic compaction. 0 disables it (manual /compact still works).
	CompactAt int `json:"compact_at,omitempty"`
	// AutoInstructions controls automatic loading of the AGENTS.md hierarchy
	// (walking up from the working directory) into the system prompt. Defaults
	// on; set false to disable. A pointer distinguishes unset from false.
	AutoInstructions *bool                     `json:"auto_instructions,omitempty"`
	Providers        map[string]ProviderConfig `json:"providers"`
	Shapes           map[string]Shape          `json:"shapes,omitempty"`
}

// Path returns the config file location, honoring ERG_CONFIG then XDG. The
// explicit flag reports whether the location came from ERG_CONFIG: an explicit
// path the caller chose is a precondition, whereas the XDG default is a mere
// convention that may be absent.
func Path() (path string, explicit bool, err error) {
	if p := os.Getenv("ERG_CONFIG"); p != "" {
		return p, true, nil
	}
	dir, err := os.UserConfigDir()
	if err != nil {
		return "", false, err
	}
	return filepath.Join(dir, "erg", "config.json"), false, nil
}

// Load reads and merges the config file over the built-in defaults. A missing
// XDG-default file is not an error: the defaults stand. A missing file named
// explicitly via ERG_CONFIG is an error, because the caller asked for that file.
func Load() (*Config, error) {
	cfg := Default()
	path, explicit, err := Path()
	if err != nil {
		return cfg, nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			if explicit {
				return nil, fmt.Errorf("ERG_CONFIG points at %s, which does not exist", path)
			}
			return cfg, nil
		}
		return nil, fmt.Errorf("read config %s: %w", path, err)
	}
	if err := merge(cfg, data); err != nil {
		return nil, fmt.Errorf("parse config %s: %w", path, err)
	}
	return cfg, nil
}

// merge decodes user config over the defaults. User-provided maps replace the
// corresponding default entries key by key; scalar fields override when set.
func merge(cfg *Config, data []byte) error {
	var user Config
	if err := json.Unmarshal(data, &user); err != nil {
		return err
	}
	if user.DefaultProvider != "" {
		cfg.DefaultProvider = user.DefaultProvider
	} else if len(user.Providers) > 0 {
		// The user supplied their own providers but no default. Don't silently
		// fall back to the built-in `local` provider — clear the default so a
		// run with no explicit provider/shape errors with the available list.
		cfg.DefaultProvider = ""
	}
	if user.DefaultShape != "" {
		cfg.DefaultShape = user.DefaultShape
	}
	if user.SystemBase != "" {
		cfg.SystemBase = user.SystemBase
	}
	if user.CompactAt != 0 {
		cfg.CompactAt = user.CompactAt
	}
	if user.AutoInstructions != nil {
		cfg.AutoInstructions = user.AutoInstructions
	}
	for name, p := range user.Providers {
		cfg.Providers[name] = p
	}
	if cfg.Shapes == nil {
		cfg.Shapes = map[string]Shape{}
	}
	for name, s := range user.Shapes {
		s.Name = name
		cfg.Shapes[name] = s
	}
	return nil
}

package config

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/emergingrobotics/erg/internal/skill"
)

// availableProviders returns the configured provider names, sorted.
func availableProviders(cfg *Config) string {
	names := make([]string, 0, len(cfg.Providers))
	for name := range cfg.Providers {
		names = append(names, name)
	}
	sort.Strings(names)
	return strings.Join(names, ", ")
}

// Overrides carry the most-explicit inputs (CLI flags, environment) that win
// over the config file and any selected shape. Empty fields defer to lower
// layers. Resolution order, most explicit first:
//
//	CLI flag  >  environment variable  >  shape  >  config default
type Overrides struct {
	Shape    string
	Provider string
	Model    string
	Effort   string
	Loop     LoopMode
}

// Resolved is the effective run configuration handed to the wiring layer to
// build the provider, toolset, and driver.
type Resolved struct {
	Shape    Shape
	Provider ProviderConfig
	Model    string
	Effort   string
	System   string
	Loop     LoopMode
	MaxTurns int
	Tools    []string
	Observe  *ObserveConfig
}

// Resolve computes the effective run configuration from the config, a selected
// shape, and the overrides.
func Resolve(cfg *Config, ov Overrides) (Resolved, error) {
	shapeName := firstNonEmpty(ov.Shape, cfg.DefaultShape)
	var shape Shape
	if shapeName != "" {
		s, ok := cfg.Shapes[shapeName]
		if !ok {
			return Resolved{}, fmt.Errorf("unknown shape %q", shapeName)
		}
		shape = s
	}

	providerName := firstNonEmpty(ov.Provider, shape.Provider, cfg.DefaultProvider)
	if providerName == "" {
		return Resolved{}, fmt.Errorf("no default_provider set; choose one with --provider or set default_provider (available: %s)", availableProviders(cfg))
	}
	pc, ok := cfg.Providers[providerName]
	if !ok {
		return Resolved{}, fmt.Errorf("unknown provider %q (available: %s)", providerName, availableProviders(cfg))
	}

	model := firstNonEmpty(ov.Model, shape.Model, pc.Model)

	loop := shape.Loop
	if ov.Loop != "" {
		loop = ov.Loop
	}
	if loop == "" {
		loop = LoopInteractive
	}

	system, err := composeSystem(cfg.SystemBase, shape, cfg.autoInstructionsEnabled())
	if err != nil {
		return Resolved{}, err
	}

	return Resolved{
		Shape:    shape,
		Provider: pc,
		Model:    model,
		Effort:   firstNonEmpty(ov.Effort, shape.Effort),
		System:   system,
		Loop:     loop,
		MaxTurns: shape.MaxTurns,
		Tools:    shape.Tools,
		Observe:  shape.Observe,
	}, nil
}

// filePrefix marks a system-prompt string that names a file to read instead of
// being used literally: `"system": "FILE: ./prompts/coder.md"`.
const filePrefix = "FILE:"

// resolveText returns s unchanged, or the contents of the file it names when s
// begins with the FILE: prefix. A named file that cannot be read is an error —
// a shape that points at a prompt file requires that file to exist.
func resolveText(s string) (string, error) {
	rest, ok := strings.CutPrefix(s, filePrefix)
	if !ok {
		return s, nil
	}
	path := strings.TrimSpace(rest)
	if path == "" {
		return "", fmt.Errorf("system: %s requires a path", filePrefix)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return "", fmt.Errorf("read system prompt file %s: %w", path, err)
	}
	return strings.TrimSpace(string(data)), nil
}

// composeSystem builds the effective system prompt: the base, then the shape's
// inline append or its @file, then any project instruction files, then the
// instructions of any SKILL.md skills the shape lists. The base and the shape's
// `system` each support the FILE: prefix to load from a file.
func composeSystem(base string, shape Shape, autoInstructions bool) (string, error) {
	baseText, err := resolveText(strings.TrimSpace(base))
	if err != nil {
		return "", err
	}
	parts := []string{baseText}

	if shape.SystemFile != "" {
		data, err := os.ReadFile(shape.SystemFile)
		if err != nil {
			return "", fmt.Errorf("read system_file %s: %w", shape.SystemFile, err)
		}
		parts = append(parts, strings.TrimSpace(string(data)))
	}
	if s := strings.TrimSpace(shape.System); s != "" {
		text, err := resolveText(s)
		if err != nil {
			return "", err
		}
		parts = append(parts, text)
	}
	if autoInstructions {
		dir, err := os.Getwd()
		if err != nil {
			return "", err
		}
		agents, err := agentsHierarchy(dir)
		if err != nil {
			return "", err
		}
		if agents != "" {
			parts = append(parts, agents)
		}
	}
	for _, path := range shape.Instr {
		data, err := os.ReadFile(path)
		if err != nil {
			return "", fmt.Errorf("read instructions %s: %w", path, err)
		}
		parts = append(parts, strings.TrimSpace(string(data)))
	}
	if len(shape.Skills) > 0 {
		skills, err := skill.LoadAll(shape.Skills)
		if err != nil {
			return "", err
		}
		parts = append(parts, skill.Section(skills))
	}

	nonEmpty := parts[:0]
	for _, p := range parts {
		if p != "" {
			nonEmpty = append(nonEmpty, p)
		}
	}
	return strings.Join(nonEmpty, "\n\n"), nil
}

// autoInstructionsEnabled reports whether AGENTS.md auto-loading is on. It
// defaults on; a config may disable it with `"auto_instructions": false`.
func (c *Config) autoInstructionsEnabled() bool {
	return c.AutoInstructions == nil || *c.AutoInstructions
}

// agentsHierarchy reads every AGENTS.md from dir upward and returns their
// contents joined outermost-first (so the nearest, most-specific file wins by
// appearing last). The walk stops at the repository root (a directory holding
// `.git`), the home directory, or the filesystem root — it never reads above
// home. It returns "" when no AGENTS.md is found.
func agentsHierarchy(dir string) (string, error) {
	home, _ := os.UserHomeDir()
	var contents []string // nearest first
	for i := 0; i < 40; i++ {
		path := filepath.Join(dir, "AGENTS.md")
		data, err := os.ReadFile(path)
		if err == nil {
			if s := strings.TrimSpace(string(data)); s != "" {
				contents = append(contents, s)
			}
		} else if !os.IsNotExist(err) {
			return "", fmt.Errorf("read %s: %w", path, err)
		}

		if isDir(filepath.Join(dir, ".git")) || dir == home {
			break
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	// Reverse to outermost-first.
	for i, j := 0, len(contents)-1; i < j; i, j = i+1, j-1 {
		contents[i], contents[j] = contents[j], contents[i]
	}
	return strings.Join(contents, "\n\n"), nil
}

func isDir(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}

// APIKey returns the API key for a provider, read from its configured env var.
// A provider with no APIKeyEnv (e.g. local) returns an empty key and no error.
func (pc ProviderConfig) APIKey() string {
	if pc.APIKeyEnv == "" {
		return ""
	}
	return os.Getenv(pc.APIKeyEnv)
}

func firstNonEmpty[T ~string](vals ...T) T {
	for _, v := range vals {
		if v != "" {
			return v
		}
	}
	var zero T
	return zero
}

package session

import (
	"testing"

	"github.com/emergingrobotics/erg/internal/agent"
)

func store(t *testing.T) *Store {
	t.Helper()
	t.Setenv("ERG_SESSIONS", t.TempDir())
	s, err := Open()
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	return s
}

func TestSaveLoadRoundTrip(t *testing.T) {
	s := store(t)
	id := NewID()
	items := []agent.Item{
		{Kind: agent.ItemUserText, Text: "hello"},
		{Kind: agent.ItemToolCall, Call: &agent.ToolCall{ID: "c1", Name: "read", Args: []byte(`{"path":"x"}`)}},
		{Kind: agent.ItemToolResult, Result: &agent.ToolResult{CallID: "c1", Name: "read", Content: "data"}},
		{Kind: agent.ItemAssistantText, Text: "done"},
	}
	meta := Meta{ID: id, Cwd: "/repo", Shape: "spec-implementer", Model: "mock"}
	if err := s.Save(meta, items); err != nil {
		t.Fatalf("save: %v", err)
	}

	gotMeta, gotItems, err := s.Load(id)
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	if gotMeta.Cwd != "/repo" || gotMeta.Shape != "spec-implementer" {
		t.Fatalf("meta round-trip wrong: %+v", gotMeta)
	}
	if len(gotItems) != 4 {
		t.Fatalf("expected 4 items, got %d", len(gotItems))
	}
