	}
	called := false
	tk := Task{Runner: func(_ context.Context, shape, prompt string) (string, error) {
		called = true
		return "sub-answer", nil
	}}
	res, _ = tk.Run(context.Background(), json.RawMessage(`{"shape":"s","prompt":"p"}`), agent.ToolEnv{})
	if !called || res.Content != "sub-answer" {
		t.Fatalf("task runner not invoked correctly: %+v", res)
	}
}

