package config

// defaultSystemBase is erg's baseline system prompt. It favors restraint over
// enforcement: there is no in-process permission gate, so the prompt tells the
// model to avoid destructive and irreversible actions unless asked.
const defaultSystemBase = `You are erg, a terminal-native software agent. Work directly and concisely.

Operating rules:
- Prefer reading before changing. Make surgical edits that match the surrounding code.
- Never run destructive git operations (reset --hard, push --force, branch -D) or delete data
  unless the user explicitly asks. Ask before any irreversible action.
- Use the provided tools. To use a capability that is not a built-in tool, run its CLI via bash.
- When a task is done, stop. Report what you did plainly; if something failed, say so.`

// Default returns the built-in configuration: three provider families wired to
// their conventional endpoints, a baseline system prompt, and starter shapes.
// A local provider needs no API key and is the zero-config default.
func Default() *Config {
	return &Config{
		DefaultProvider: "local",
		DefaultShape:    "",
		SystemBase:      defaultSystemBase,
		// Auto-compact once the visible window is a long conversation. Rough
		// estimate (~4 chars/token); tune per your model's context, 0 disables.
		CompactAt: 12000,
		Providers: map[string]ProviderConfig{
			"local": {
				Type:    "local",
				BaseURL: "http://127.0.0.1:11434", // Ollama default; llama.cpp is :8080
			},
			"openai": {
				Type:      "openai",
				BaseURL:   "https://api.openai.com/v1",
				APIKeyEnv: "OPENAI_API_KEY",
				Model:     "gpt-4o",
			},
			"anthropic": {
				Type:      "anthropic",
				BaseURL:   "https://api.anthropic.com/v1",
				APIKeyEnv: "ANTHROPIC_API_KEY",
				Model:     "claude-sonnet-4-5",
			},
			// Offline echo provider: runs erg with no model backend.
			"mock": {Type: "mock"},
		},
		Shapes: map[string]Shape{
			"design-partner": {
				Name: "design-partner",
				Loop: LoopInteractive,
				System: "Act as a thinking partner. Reason about design and tradeoffs before " +
					"proposing changes. Prefer discussion over editing; do not write files unless asked.",
				Tools: []string{"read", "bash"},
			},
			"spec-implementer": {
				Name: "spec-implementer",
				Loop: LoopOneshot,
				System: "Implement the work to the written specification. Follow it exactly; if it is " +
					"ambiguous, state the assumption and proceed. Run the tests when you are done.",
				MaxTurns: 100,
			},
			"telemetry-watcher": {
				Name:   "telemetry-watcher",
				Loop:   LoopObserve,
				System: "Watch the incoming telemetry. React only to notable events; summarize briefly.",
				Tools:  []string{"read", "bash"},
				Observe: &ObserveConfig{
					Source:  SourceConfig{Kind: "stdin"},
					Trigger: TriggerConfig{Kind: "every"},
					Prompt:  "A telemetry event arrived:\n{{.Event}}\n\nAssess it and act if warranted.",
				},
			},
		},
	}
}
